export const LEAVE_RETRY_MS = 300;

export type SettledLeaveDecision = 'navigate' | 'ignore';
export type UnsettledHeaderBack = 'go-back' | 'replace-main-tabs';

export interface SettledLeaveInput {
  settled: boolean;
  currentRouteName?: string;
  waitingRoomRouteName: string;
  now: number;
  lastAttemptAt: number;
}

// PayMe resume can drop the first leave, and a permanent lock then makes the
// header back look dead. Ignore only a burst of calls; a later press retries.
export const decideSettledLeave = (
  input: SettledLeaveInput,
): SettledLeaveDecision => {
  if (!input.settled) {
    return 'ignore';
  }
  if (
    input.currentRouteName != null &&
    input.currentRouteName !== input.waitingRoomRouteName
  ) {
    return 'ignore';
  }
  if (input.now - input.lastAttemptAt < LEAVE_RETRY_MS) {
    return 'ignore';
  }
  return 'navigate';
};

export const decideUnsettledHeaderBack = (
  canGoBack: boolean,
): UnsettledHeaderBack =>
  canGoBack ? 'go-back' : 'replace-main-tabs';

import {
  decideSettledLeave,
  decideUnsettledHeaderBack,
  LEAVE_RETRY_MS,
} from '../src/screens/product-waiting-room/payment-header-back';

const WAITING_ROOM = 'ProductWaitingRoomScreen';

describe('payment header back', () => {
  it('leaves a settled payment that is still on the waiting room', () => {
    expect(decideSettledLeave({
      settled: true,
      currentRouteName: WAITING_ROOM,
      waitingRoomRouteName: WAITING_ROOM,
      now: 1_000,
      lastAttemptAt: 0,
    })).toBe('navigate');
  });

  it('retries when an earlier leave did not move off this screen', () => {
    expect(decideSettledLeave({
      settled: true,
      currentRouteName: WAITING_ROOM,
      waitingRoomRouteName: WAITING_ROOM,
      now: 1_000 + LEAVE_RETRY_MS,
      lastAttemptAt: 1_000,
    })).toBe('navigate');
  });

  it('ignores a second leave in the same burst', () => {
    expect(decideSettledLeave({
      settled: true,
      currentRouteName: WAITING_ROOM,
      waitingRoomRouteName: WAITING_ROOM,
      now: 1_000,
      lastAttemptAt: 1_000,
    })).toBe('ignore');
  });

  it('does not leave again after the route has already changed', () => {
    expect(decideSettledLeave({
      settled: true,
      currentRouteName: 'HealsPlanScreen',
      waitingRoomRouteName: WAITING_ROOM,
      now: 5_000,
      lastAttemptAt: 0,
    })).toBe('ignore');
  });

  it('treats a missing route as still on this screen', () => {
    expect(decideSettledLeave({
      settled: true,
      currentRouteName: undefined,
      waitingRoomRouteName: WAITING_ROOM,
      now: 1_000,
      lastAttemptAt: 0,
    })).toBe('navigate');
  });

  it('goes back when payment is not settled and the stack can pop', () => {
    expect(decideUnsettledHeaderBack(true)).toBe('go-back');
  });

  it('replaces the main tabs when the return intent left nowhere to go back', () => {
    expect(decideUnsettledHeaderBack(false)).toBe('replace-main-tabs');
  });
});

